design.css:
/* Coral — the Zangetsu look (docs/theme-references/zangetsu.md): near-black, one coral accent, Nunito. */

/* Wordmark: white uppercase lettering, like the app's own. */
[data-part="brand.text"] { font-weight: 900; font-size: 22px; letter-spacing: 0.12em; text-transform: uppercase; color: #fff; }
@media (max-width: 640px) { [data-part="brand.mark"] { display: none !important; } }

/* Featured hero: a rounded art card inset from the edges, glowing in the artwork's own colour. */
[data-slot="home.hero"] {
  margin: 8px 16px 28px !important;
  width: auto !important;
  border-radius: 28px;
  overflow: hidden;
  box-shadow: 0 18px 70px -10px rgb(var(--hero-ambient-rgb, 255 77 87) / 0.55);
}
/* Desktop: clear the window's title strip above the card. */
@media (min-width: 641px) { [data-slot="home.hero"] { margin-top: 44px !important; } }
[data-part="coral.hero"]::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(11, 11, 15, 0.95), rgba(11, 11, 15, 0.35) 45%, rgba(11, 11, 15, 0) 65%) !important;
  pointer-events: none;
}
[data-part="coral.hero"]::after { z-index: 1; }
[data-part="coral.hero"] > :not(:first-child) { z-index: 2; }
[data-part="coral.info"] { padding-bottom: 36px; }
[data-part="coral.meta"] { width: 100%; overflow: visible !important; text-transform: uppercase; letter-spacing: 0.8px; }
[data-part="coral.play"] { width: 138px; justify-content: center; gap: 8px; }
[data-part="coral.glass"] { width: 44px; justify-content: center; padding: 0; background: rgba(255, 255, 255, 0.14) !important; backdrop-filter: blur(10px); line-height: 1; }
[data-part="hero.dot"] { width: 6px; height: 6px; border-radius: 3px; background: rgba(255, 255, 255, 0.35); }
[data-part="hero.dot"][data-active] { width: 20px; background: #fff; }

/* Rows: 20 px headings with a wide gap above, a "See All" link in the accent. */
[data-part="row.title"], [data-part="block.title"] { font-size: 20px; font-weight: 700; letter-spacing: -0.3px; color: #fff; }
[data-part="row.more"] { color: #ff4d57; font-weight: 600; }

/* Poster cards: bottom scrim, the ★ score pill top right, a fixed two-line title. */
[data-part="coral.poster"]::after {
  content: "";
  position: absolute;
  inset: 55% 0 0;
  border-radius: 0 0 12px 12px;
  background: linear-gradient(to top, rgba(11, 11, 15, 0.7), rgba(11, 11, 15, 0));
  pointer-events: none;
}
[data-part="coral.score"] { margin: 6px; background: rgba(0, 0, 0, 0.6); z-index: 1; }
[data-part="coral.card-title"] { line-height: 1.3; min-height: 2.6em; }

/* Series page ("Netflix header"): 28 px title, a full-width white Play, a three-line synopsis. */
[data-slot="detail"][data-variant="phone"] [data-part="detail.title"] { font-size: 28px; font-weight: 800; }
[data-slot="detail"] [data-part="button"][data-variant="primary"] { border-radius: 8px; background: #fff; color: #0b0b0f; }
[data-slot="detail"][data-variant="phone"] [data-part="button"][data-variant="primary"] { width: 100%; height: 52px; justify-content: center; font-size: 16px; }
[data-slot="detail"] [data-part="detail.synopsis"] { -webkit-line-clamp: 3; }
[data-slot="detail"] [data-part="detail.meta"] { color: #a7a7b2; font-weight: 500; }
/* Phone: no poster card; the title block sits on the artwork's lower edge. */
[data-slot="detail"][data-variant="phone"] [data-part="detail.poster"],
[data-slot="detail"][data-variant="phone"] [data-part="detail.alt-title"],
[data-slot="detail"][data-variant="phone"] [data-part="detail.meta"] { display: none; }
[data-slot="detail"][data-variant="phone"] [data-part="button"][data-variant="secondary"] { border-radius: 8px; border: 0; background: #20212a; color: #fff; }
/* Episode rows: a 16:9 radius-10 thumbnail beside the title, no card fill. */
[data-slot="detail"][data-variant="phone"] [data-part="episode"]:has(> [data-part="episode.still"]) { grid-template-columns: 124px 1fr; align-items: center; gap: 4px; background: transparent; border-radius: 0; }
[data-slot="detail"][data-variant="phone"] [data-part="episode.still"] { min-height: 0; height: auto; border-radius: 10px; }
/* Genres as soft accent tags. */
[data-part="detail.genres"] [data-part="chip"] {
  padding: 3px 7px;
  border: 0;
  border-radius: 6px;
  background: rgba(255, 77, 87, 0.15);
  color: #ff4d57;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.8px;
  text-transform: uppercase;
}

/* Left-anchored underline tabs: accent label and indicator on the active tab, grey otherwise. */
[data-slot="detail"] [data-part="tab"] { font-size: 15px; font-weight: 500; color: #a7a7b2; }
[data-slot="detail"] [data-part="tab"][data-active] { font-weight: 600; color: #ff4d57; }
[data-slot="detail"] [data-part="tab"][data-active] > span { left: 12px; right: 12px; bottom: 0; height: 2.5px; background: #ff4d57; }
[data-slot="detail"] [data-part="tabs"][data-variant="underline"] { border-bottom: 0; }

/* The floating dock: frosted capsule, 7 % white hairline, colour-and-glyph active state only. */
[data-slot="nav.bottom"] { border-color: rgba(255, 255, 255, 0.07) !important; }
